CREATE TABLE payroll(
  payroll_id INTEGER PRIMARY KEY,
  employee_id TEXT NOT NULL REFERENCES employees(employee_id) ON DELETE CASCADE,
  annual_salary REAL NOT NULL CHECK(annual_salary > 0),
  pay_period TEXT NOT NULL
);
